const escapeHTML = value => String(value ?? "").replace(/[&<>"']/g, c => ({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"})[c]);
const date = value => new Date(value).toLocaleDateString("zh-CN", {year:"numeric",month:"short",day:"numeric"});
const dateTime = value => new Date(value).toLocaleString("zh-CN", {month:"numeric",day:"numeric",hour:"2-digit",minute:"2-digit",hour12:false});
const host = value => { try { return new URL(value).hostname; } catch { return ""; } };
const textList = value => Array.isArray(value) ? value.filter(x => typeof x === "string").slice(0,4).join(" · ") : typeof value === "string" ? value : "";
const plainToRich = value => String(value || "").split(/\n/).map(line => `<div>${escapeHTML(line) || "<br>"}</div>`).join("");
