async function api(url, options) {
  const response = await fetch(url, options);
  const data = await response.json();
  if (!response.ok) throw new Error(data.error?.message || "请求失败，请重试");
  return data;
}

function navigate(url) {
  history.pushState({}, "", url);
  window.scrollTo(0,0);
  render();
}

function shell(content, current, title) {
  const params = new URLSearchParams(location.search);
  const active = key => current === key ? "selected" : "";
  root.innerHTML = `<div class="shell">
    <aside class="sidebar">
      <a class="brand" href="/" data-nav><span class="brand-mark">s<span>·</span></span>silo</a>
      <div class="space-label">信息筒仓</div>
      <nav>
        <a class="${active("library")}" href="/" data-nav>${ICON.library}资产库</a>
        <a class="${active("discover")}" href="/discover" data-nav>${ICON.compass}发现</a>
        <a class="${active("interested")}" href="/interested" data-nav>${ICON.star}感兴趣</a>
        <a class="${active("new")}" href="/new" data-nav>${ICON.plus}新建资产</a>
        <a class="${active("import")}" href="/import" data-nav>${ICON.upload}导入收藏夹</a>
        <a class="${active("archived")}" href="/?status=archived" data-nav>${ICON.archive}已归档</a>
        <a class="${active("organize")}" href="/?explore_level=none" data-nav>${ICON.check}集中整理</a>
        <a class="${active("data")}" href="/data" data-nav>${ICON.database}数据管理</a>
      </nav>
      <div class="sidebar-foot"><span class="local-dot"></span>本地信息，随时找回<div>数据随 Skill 一起保存</div></div>
    </aside>
    <main><header class="topbar"><span>信息筒仓 ${ICON.chevron} ${escapeHTML(title)}</span><span class="local-pill">本机 · 私人</span></header>${content}</main>
  </div>`;
  root.querySelectorAll("[data-nav]").forEach(link => link.addEventListener("click", event => { event.preventDefault(); navigate(link.getAttribute("href")); }));
}

function showLoading(title="资产库") { shell(`<div class="content"><p class="muted">正在读取本地数据…</p></div>`, "", title); }
function showError(error, title="资产库") { shell(`<div class="content"><div role="alert" class="error">${escapeHTML(error.message || error)}</div></div>`, "", title); }
function assetTitle(asset) {
  if (asset.title.length <= 76) return asset.title;
  if (asset.asset_type === "github" && asset.source_url) {
    try { const parts = new URL(asset.source_url).pathname.split("/").filter(Boolean); if (parts.length >= 2) return `${parts[0]}/${parts[1]}`; } catch {}
  }
  return asset.title.slice(0,73) + "…";
}
function typeIcon(type) { return `<span class="asset-icon ${escapeHTML(type)}">${TYPE_ICONS[type] || TYPE_ICONS.other}</span>`; }
function setQuery(key, value) {
  const params = new URLSearchParams(location.search);
  params.delete("page"); params.delete(key);
  if (value) params.append(key, value);
  navigate("/?" + params.toString());
}

async function libraryPage() {
  showLoading();
  const params = new URLSearchParams(location.search);
  const status = params.get("status") || "active";
  try {
    const [results,tags,folders] = await Promise.all([
      api("/api/assets?" + params.toString()), api("/api/tags?status=" + encodeURIComponent(status)), api("/api/folders?status=" + encodeURIComponent(status))
    ]);
    const folderLeaves = new Set(folders.flatMap(f => [f.name, f.name.split("/").at(-1) || f.name]));
    const contentTags = tags.filter(t => (t.usage_count || 0) > 0 && !folderLeaves.has(t.name));
    const filtered = ["q","asset_type","tags","folders","explore_level"].some(k => params.get(k));
    const heading = status === "archived" ? "已归档" : params.get("explore_level") === "none" ? "集中整理" : "资产库";
    const current = status === "archived" ? "archived" : params.get("explore_level") === "none" ? "organize" : "library";
    const options = (items,value,label) => `<option value="">${label}</option>` + items.map(([v,n]) => `<option value="${escapeHTML(v)}" ${value===v?"selected":""}>${escapeHTML(n)}</option>`).join("");
    const cards = results.items.map(a => {
      const short = assetTitle(a); const tagsHTML = a.tags.filter(t => !folderLeaves.has(t.name)).slice(0,3).map(t => `<span class="tag">${escapeHTML(t.name)}</span>`).join("");
      return `<article class="asset-row" data-id="${a.id}" data-revision="${a.revision}">
        <input hidden class="row-check" type="checkbox" aria-label="选择 ${escapeHTML(short)}">
        <a class="asset-card" href="/assets/${a.id}" data-nav>${typeIcon(a.asset_type)}<div class="asset-body"><div class="asset-title"><h2>${escapeHTML(short)}</h2><span class="level ${a.explore_level}">${LEVELS[a.explore_level]}</span></div>${short!==a.title?`<div class="source-title">${escapeHTML(a.title)}</div>`:""}<p>${escapeHTML(a.match_excerpt || a.summary || (a.source_url ? host(a.source_url) : "尚未添加摘要"))}</p><div class="asset-meta"><span>${TYPES[a.asset_type] || a.asset_type}</span>${tagsHTML}<time>${date(a.updated_at)}</time></div></div>${ICON.arrow}</a></article>`;
    }).join("");
    const empty = !results.items.length ? `<div class="empty"><div class="empty-icon">${ICON.library}</div><h2>${filtered?"没有找到匹配的资产":"从一个值得留下的发现开始"}</h2><p>${filtered?"试试更短的关键词或清除筛选。":"记录一个灵感、笔记、网址或文件，之后可以继续交给 Agent 探索。"}</p><button data-action="${filtered?"clear":"new"}">${filtered?"查看全部资产":"记录第一项资产"}${ICON.arrow}</button></div>` : "";
    const pagination = results.total > results.page_size ? `<div class="pagination"><button data-page="${results.page-1}" ${results.page===1?"disabled":""}>上一页</button><span>${results.page} / ${Math.ceil(results.total/results.page_size)}</span><button data-page="${results.page+1}" ${results.page*results.page_size>=results.total?"disabled":""}>下一页</button></div>` : "";
    const content = `<div class="content library-page">
      <div class="page-title compact"><div><div class="eyebrow">YOUR KNOWLEDGE, WITHIN REACH</div><h1>${heading}</h1><p>${results.total} 项资产，搜索、分类或集中整理。</p></div><button class="primary" data-action="new">${ICON.plus}<span>记录新资产</span></button></div>
      <div id="notice"></div>
      <form class="searchbox prominent" id="search-form">${ICON.search}<input aria-label="搜索资产" name="q" value="${escapeHTML(params.get("q")||"")}" placeholder="搜索标题、摘要、报告或标签…"><button>搜索</button></form>
      <div class="filters">
        <label>类型<select data-filter="asset_type">${options(Object.entries(TYPES),params.get("asset_type")||"","全部类型")}</select></label>
        <label>探索<select data-filter="explore_level">${options(Object.entries(LEVELS),params.get("explore_level")||"","全部状态")}</select></label>
        <label>内容标签<select data-filter="tags"><option value="">全部标签</option>${contentTags.map(t=>`<option value="${t.id}" ${params.get("tags")===t.id?"selected":""}>${FACETS[t.facet]} · ${escapeHTML(t.name)}</option>`).join("")}</select></label>
        <label>收藏目录<select data-filter="folders"><option value="">全部目录</option>${folders.map(f=>`<option value="${escapeHTML(f.name)}" ${params.get("folders")===f.name?"selected":""}>${escapeHTML(f.name)} · ${f.usage_count}</option>`).join("")}</select></label>
        <button class="text-button" id="browse-button" type="button">${ICON.folder}浏览分类</button>
        ${filtered?`<button class="text-button" data-action="clear">× 清除筛选</button>`:""}
      </div>
      <section class="category-panel" id="category-panel" hidden><div class="category-heading"><div><h2>分类浏览</h2><p>内容标签描述资源本身；收藏目录保留原来的收纳位置。</p></div><input id="category-query" placeholder="查找分类…"></div><div class="category-group"><h3>${ICON.tags}内容标签</h3><div class="category-tags" id="content-categories">${contentTags.slice(0,40).map(t=>`<button data-category="tags" data-value="${t.id}">${escapeHTML(t.name)}<span>${t.usage_count}</span></button>`).join("")}</div></div><div class="category-group"><h3>${ICON.folder}原收藏目录</h3><div class="category-tags folders" id="folder-categories">${folders.slice(0,30).map(f=>`<button data-category="folders" data-value="${escapeHTML(f.name)}">${escapeHTML(f.name)}<span>${f.usage_count}</span></button>`).join("")}</div></div></section>
      <div class="list-heading"><span>${results.total} 项资产</span><div><button class="text-button" id="select-button">${ICON.check}批量整理</button><span>${params.get("q")?"按相关度排序":"最近更新"}</span></div></div>
      <div class="bulk-bar" id="bulk-bar" hidden><label><input type="checkbox" id="select-all">选择本页</label><strong><span id="selected-count">0</span> 项</strong><select id="bulk-facet">${Object.entries(FACETS).map(([v,n])=>`<option value="${v}">${n}</option>`).join("")}</select><input id="bulk-tag" placeholder="添加标签"><button id="add-tag">应用标签</button><select id="remove-tag"><option value="">选择错误标签</option>${contentTags.map(t=>`<option value="${t.id}">${escapeHTML(t.name)}</option>`).join("")}</select><button id="remove-tag-button">移除标签</button><button id="archive-selected">${status==="archived"?"恢复":"归档"}</button></div>
      ${empty}<div class="asset-list compact-list">${cards}</div>${pagination}<footer class="list-footer">收录是开始，找回才是价值。</footer>
    </div>`;
    shell(content,current,heading); bindLibrary(results,status);
  } catch (error) { showError(error); }
}

function bindLibrary(results,status) {
  root.querySelectorAll("[data-action]").forEach(button => button.addEventListener("click", () => navigate(button.dataset.action === "new" ? "/new" : "/")));
  root.querySelector("#search-form")?.addEventListener("submit", event => { event.preventDefault(); setQuery("q", new FormData(event.target).get("q")); });
  root.querySelectorAll("[data-filter]").forEach(select => select.addEventListener("change", () => setQuery(select.dataset.filter,select.value)));
  root.querySelectorAll("[data-category]").forEach(button => button.addEventListener("click", () => setQuery(button.dataset.category,button.dataset.value)));
  root.querySelectorAll("[data-page]").forEach(button => button.addEventListener("click", () => setQuery("page",button.dataset.page)));
  const panel=root.querySelector("#category-panel"), browse=root.querySelector("#browse-button");
  browse?.addEventListener("click",()=>{panel.hidden=!panel.hidden;browse.lastChild.textContent=panel.hidden?"浏览分类":"收起分类"});
  root.querySelector("#category-query")?.addEventListener("input",event=>{const q=event.target.value.toLowerCase();panel.querySelectorAll("[data-value]").forEach(b=>b.hidden=!b.textContent.toLowerCase().includes(q))});
  const selectButton=root.querySelector("#select-button"), bulkBar=root.querySelector("#bulk-bar"), checks=[...root.querySelectorAll(".row-check")];
  const updateCount=()=>{const count=checks.filter(c=>c.checked).length;root.querySelector("#selected-count").textContent=count;root.querySelector("#select-all").checked=!!checks.length&&count===checks.length;checks.forEach(c=>c.closest(".asset-row").classList.toggle("selected",c.checked))};
  selectButton?.addEventListener("click",()=>{const active=bulkBar.hidden;bulkBar.hidden=!active;checks.forEach(c=>{c.hidden=!active;c.checked=false});selectButton.lastChild.textContent=active?"退出批量":"批量整理";updateCount()});
  checks.forEach(c=>c.addEventListener("change",updateCount));
  root.querySelector("#select-all")?.addEventListener("change",event=>{checks.forEach(c=>c.checked=event.target.checked);updateCount()});
  const bulk=async action=>{const rows=checks.filter(c=>c.checked).map(c=>c.closest(".asset-row"));if(!rows.length)return;try{const result=await api("/api/assets",{method:"PATCH",headers:{"Content-Type":"application/json"},body:JSON.stringify({items:rows.map(r=>({id:r.dataset.id,revision:Number(r.dataset.revision)})),...action})});await libraryPage();const notice=root.querySelector("#notice");if(notice)notice.innerHTML=`<div role="status" class="notice">${ICON.check}已更新 ${result.updated} 项资产</div>`}catch(error){alert(error.message)}};
  root.querySelector("#add-tag")?.addEventListener("click",()=>{const name=root.querySelector("#bulk-tag").value.trim();if(name)bulk({add_tags:[{name,facet:root.querySelector("#bulk-facet").value}]})});
  root.querySelector("#remove-tag-button")?.addEventListener("click",()=>{const id=root.querySelector("#remove-tag").value;if(id)bulk({remove_tag_ids:[id]})});
  root.querySelector("#archive-selected")?.addEventListener("click",()=>bulk({status:status==="archived"?"active":"archived"}));
}

function markdown(source) {
  const inline = text => escapeHTML(text).replace(/\*\*([^*]+)\*\*/g,"<strong>$1</strong>").replace(/`([^`]+)`/g,"<code>$1</code>").replace(/\[([^\]]+)\]\((https?:\/\/[^\s)]+)\)/g,'<a href="$2" target="_blank" rel="noreferrer">$1</a>');
  const lines=String(source||"").split(/\r?\n/);let output="",listTag="",code=false,buffer=[];
  const closeList=()=>{if(listTag){output+=`</${listTag}>`;listTag=""}};
  const cells=line=>line.trim().replace(/^\||\|$/g,"").split("|").map(x=>x.trim());
  for(let i=0;i<lines.length;i++){const line=lines[i];if(line.startsWith("```")){closeList();if(code){output+=`<pre><code>${escapeHTML(buffer.join("\n"))}</code></pre>`;buffer=[]}code=!code;continue}if(code){buffer.push(line);continue}
    if(line.includes("|")&&i+1<lines.length&&/^\s*\|?\s*:?-+/.test(lines[i+1])&&lines[i+1].includes("|")){closeList();const head=cells(line);i+=2;const rows=[];while(i<lines.length&&lines[i].includes("|")&&lines[i].trim()){rows.push(cells(lines[i]));i++}i--;output+=`<table><thead><tr>${head.map(x=>`<th>${inline(x)}</th>`).join("")}</tr></thead><tbody>${rows.map(row=>`<tr>${row.map(x=>`<td>${inline(x)}</td>`).join("")}</tr>`).join("")}</tbody></table>`;continue}
    const h=line.match(/^(#{1,3})\s+(.+)/);if(h){closeList();output+=`<h${h[1].length}>${inline(h[2])}</h${h[1].length}>`;continue}const item=line.match(/^\s*([-*]|\d+\.)\s+(.+)/);if(item){const wanted=/\d/.test(item[1])?"ol":"ul";if(listTag!==wanted){closeList();output+=`<${wanted}>`;listTag=wanted}output+=`<li>${inline(item[2])}</li>`;continue}closeList();if(/^\s*---+\s*$/.test(line)){output+="<hr>";continue}if(/^>\s?/.test(line)){output+=`<blockquote><p>${inline(line.replace(/^>\s?/,""))}</p></blockquote>`;continue}if(line.trim())output+=`<p>${inline(line)}</p>`}
  closeList();if(code)output+=`<pre><code>${escapeHTML(buffer.join("\n"))}</code></pre>`;return output;
}

function exploreInstruction(asset) {
  const focus=asset.asset_type==="image"?"查看原始图片附件，识别可见内容与文字，并提取真正需要保存的目标资源":asset.asset_type==="idea"?"保留原始灵感，分析问题、目标用户、关键假设、风险和下一步":asset.asset_type==="note"?"保留原始笔记，整理要点、决定、开放问题、关联主题和行动项":"核实原始资料，分析能力、使用场景、限制与价值";
  return `请使用 silo Skill 深入探索信息筒仓资产 ${asset.id}。读取现有记录，${focus}，并保存完整探索报告。`;
}
async function copyText(value){if(navigator.clipboard?.writeText){try{return await navigator.clipboard.writeText(value)}catch{}}const area=document.createElement("textarea");area.value=value;area.style.position="fixed";area.style.opacity="0";document.body.append(area);area.select();if(!document.execCommand("copy"))throw new Error("copy failed");area.remove()}

async function detailPage(id) {
  showLoading("资产详情");
  try {
    const asset=await api("/api/assets/"+encodeURIComponent(id)); const report=asset.analysis_json||null; const short=assetTitle(asset); const richContent=asset.content_html||plainToRich(asset.content_text);
    const extracted=Array.isArray(report?.extracted_assets)?report.extracted_assets.filter(x=>x&&typeof x.asset_id==="string"):[];
    const extractedHTML=extracted.length?`<section class="extracted-assets"><div><span class="eyebrow">EXTRACTED KNOWLEDGE</span><h2>从截图提取的资产</h2><p>以下内容已独立保存。截图仅作为来源证据保留。</p></div><div class="extracted-list">${extracted.map(item=>`<a href="/assets/${escapeHTML(item.asset_id)}" data-nav>${typeIcon(item.asset_type)}<span><strong>${escapeHTML(item.title)}</strong><small>${escapeHTML(TYPES[item.asset_type]||item.asset_type)}${item.source_url?" · "+escapeHTML(host(item.source_url)):""}</small></span>${ICON.arrow}</a>`).join("")}</div></section>`:"";
    const overview=report&&!extracted.length?`<section class="report-overview">${[["建议",RECS[report.recommendation]||report.recommendation||"未知"],["上手成本",({low:"低",medium:"中",high:"高",unknown:"未知"})[report.learning_cost]||"未知"],["技术栈",textList(report.tech_stack)||"未知"],["适用场景",textList(report.use_cases)||"未知"],["主要限制",textList(report.limitations)||"未知"]].map(([k,v])=>`<div><span>${k}</span><strong>${escapeHTML(v)}</strong></div>`).join("")}</section>`:"";
    const structured=report?Object.entries(report).filter(([k])=>!["report_markdown","sources","schema_version","asset_type","generated_at","extracted_assets"].includes(k)).map(([k,v])=>`<dt>${escapeHTML(REPORT_LABELS[k]||k)}</dt><dd>${escapeHTML(typeof v==="string"?v:JSON.stringify(v,null,2))}</dd>`).join(""):"";
    const sources=Array.isArray(report?.sources)?report.sources.map(s=>`<p><a href="${escapeHTML(s.url)}" target="_blank" rel="noreferrer">${escapeHTML(s.title)}</a> <small>${date(s.accessed_at)}</small></p>`).join(""):"";
    const grouped=FACET_ORDER.map(f=>[f,asset.tags.filter(t=>t.facet===f)]).filter(([,v])=>v.length).map(([f,list])=>`<div class="tag-group"><span>${FACETS[f]}</span><div>${list.map(t=>`<button data-tag="${t.id}">${escapeHTML(t.name)}</button>`).join("")}</div></div>`).join("");
    const reportHTML=report?`${markdown(report.report_markdown||"")}<details><summary>结构化分析</summary><dl class="structured">${structured}</dl></details><h3>参考来源</h3>${sources}`:`<div class="report-empty">${ICON.library}<p>还没有探索报告</p><span>复制上方探索指令，让 Agent 帮你研究它的价值。</span></div>`;
    let attachment="";if(asset.local_path){if(extracted.length&&asset.asset_type==="image")attachment=`<section class="panel"><h2>来源截图</h2><details class="source-capture"><summary>查看原始截图（包含未保留的界面信息）</summary><img class="attachment-image" src="/api/assets/${id}/preview" alt="${escapeHTML(asset.title)}"><a class="button" href="/api/assets/${id}/attachment">下载原文件${ICON.arrow}</a></details></section>`;else attachment=`<section class="panel"><h2>原始附件</h2>${asset.asset_type==="html"?`<p class="muted">静态安全预览：脚本和外部资源已禁用。</p><iframe title="HTML 静态预览" sandbox="" src="/api/assets/${id}/preview"></iframe>`:asset.asset_type==="image"?`<img class="attachment-image" src="/api/assets/${id}/preview" alt="${escapeHTML(asset.title)}">`:""}<a class="button" href="/api/assets/${id}/attachment">下载原文件${ICON.arrow}</a></section>`}
    const content=`<div class="content detail"><button class="text-button back" data-back>${ICON.back}返回资产库</button><div id="detail-message"></div>
      <div class="detail-title">${typeIcon(asset.asset_type)}<div><span class="eyebrow">${TYPES[asset.asset_type]} · ${LEVELS[asset.explore_level]}</span><h1>${escapeHTML(short)}</h1>${short!==asset.title?`<p class="original-title">原始标题：${escapeHTML(asset.title)}</p>`:""}</div></div><p class="lead">${escapeHTML(asset.summary||"尚未添加摘要")}</p>
      <div class="actions">${asset.source_url?`<a class="button primary" href="${escapeHTML(asset.source_url)}" target="_blank" rel="noreferrer">打开原始地址${ICON.arrow}</a>`:""}<button id="edit-button">编辑资产</button><button id="archive-button">${ICON.archive}${asset.status==="active"?"归档":"恢复资产"}</button><button id="copy-button">${ICON.copy}<span>复制探索指令</span></button><span class="copy-feedback" id="copy-feedback" hidden>${ICON.check}探索指令已复制</span></div>
      ${extractedHTML}      <form class="panel edit-form" id="edit-form" hidden><div class="edit-heading"><div><h2>编辑资产</h2><p>正文支持完整格式、表格、链接和图片；图片会保存到 Silo 内部。</p></div><span id="save-state"></span></div><label>标题<input name="title" required value="${escapeHTML(asset.title)}"></label><label>摘要<textarea name="summary" rows="2">${escapeHTML(asset.summary||"")}</textarea></label><label>核心价值<textarea name="core_value" rows="2">${escapeHTML(asset.core_value||"")}</textarea></label><div class="rich-field"><label for="asset-rich-editor">资产正文</label><textarea id="asset-rich-editor" name="content_html">${escapeHTML(richContent)}</textarea><small>支持标题、粗体、斜体、链接、引用、列表、代码块、表格和本地图片。可直接粘贴截图或拖入图片，单张最大 20 MiB。</small></div><label>用户备注<textarea name="note" rows="2">${escapeHTML(asset.user_note)}</textarea></label><div class="edit-row"><label>资产类型<select name="asset_type">${Object.entries(TYPES).map(([k,v])=>`<option value="${k}" ${asset.asset_type===k?"selected":""}>${v}</option>`).join("")}</select></label><label>探索级别<select name="explore_level">${Object.entries(LEVELS).map(([k,v])=>`<option value="${k}" ${asset.explore_level===k?"selected":""}>${v}</option>`).join("")}</select></label><label>状态<select name="status"><option value="active" ${asset.status==="active"?"selected":""}>活跃</option><option value="archived" ${asset.status==="archived"?"selected":""}>已归档</option></select></label></div><label>源 URL<input name="source_url" type="url" value="${escapeHTML(asset.source_url||"")}" placeholder="https://…"></label><label>规范 URL<input name="canonical_url" type="url" value="${escapeHTML(asset.canonical_url||"")}" placeholder="https://…"></label><details class="advanced-edit"><summary>高级数据</summary><p>仅在需要修复结构化数据时编辑。</p><label>元数据 JSON<textarea name="metadata_json" rows="4">${escapeHTML(JSON.stringify(asset.metadata_json||{},null,2))}</textarea></label><label>分析 JSON<textarea name="analysis_json" rows="6">${escapeHTML(asset.analysis_json?JSON.stringify(asset.analysis_json,null,2):"")}</textarea></label></details><label>标签</label><div class="tag-editor" id="tag-editor"></div><div class="add-tag"><select id="tag-facet">${Object.entries(FACETS).map(([k,v])=>`<option value="${k}">${v}</option>`).join("")}</select><input id="tag-name" placeholder="添加标签"><button type="button" id="add-detail-tag">添加</button></div><div class="edit-actions"><button class="primary" id="save-asset">保存修改</button><button type="button" id="cancel-edit">取消</button></div></form>
      ${overview}<div class="detail-grid"><div><section class="panel value-panel"><h2>为什么值得留下</h2><p>${escapeHTML(asset.core_value||"尚未记录核心价值。")}</p></section>${asset.last_explore_error?`<div class="error">最近一次探索未完成：${escapeHTML(asset.last_explore_error)}。已有报告保留。</div>`:""}<section class="panel report"><div class="section-title"><h2>探索报告</h2>${report?'<span class="level deep">已探索</span>':""}</div>${reportHTML}</section>${attachment}${richContent?`<section class="panel"><h2>${["idea","note"].includes(asset.asset_type)?"资产正文":"保存时的要求"}</h2>${asset.content_html?`<div class="saved-content">${asset.content_html}</div>`:`<pre class="content-text">${escapeHTML(asset.content_text)}</pre>`}</section>`:""}</div><aside><section class="panel"><h2>内容标签</h2><div class="detail-tags grouped">${grouped||'<p class="muted">暂无标签</p>'}</div></section>${asset.metadata_json?.bookmark_folders?.length?`<section class="panel"><h2>原收藏目录</h2>${asset.metadata_json.bookmark_folders.map(f=>`<button class="folder-link" data-folder="${escapeHTML(f)}">${ICON.folder}${escapeHTML(f)}</button>`).join("")}</section>`:""}<section class="panel"><h2>我的备注</h2><p class="preserve">${escapeHTML(asset.user_note||"留下你的想法，方便下次找回。")}</p></section><section class="metadata"><div>创建于 ${date(asset.created_at)}</div><div>更新于 ${date(asset.updated_at)}</div><div>${asset.status==="archived"?"已归档":"未归档"}</div><small>资产 ID<br>${asset.id}</small></section></aside></div></div>`;
    shell(content,"","资产详情");bindDetail(asset);
  } catch(error){showError(error,"资产详情")}
}

function bindDetail(asset){
  root.querySelector("[data-back]").addEventListener("click",()=>navigate("/"));root.querySelectorAll("[data-tag]").forEach(b=>b.addEventListener("click",()=>navigate("/?tags="+b.dataset.tag)));root.querySelectorAll("[data-folder]").forEach(b=>b.addEventListener("click",()=>navigate("/?folders="+encodeURIComponent(b.dataset.folder))));
  const form=root.querySelector("#edit-form"),tagEditor=root.querySelector("#tag-editor"),richTextarea=root.querySelector("#asset-rich-editor"),saveButton=root.querySelector("#save-asset"),saveState=root.querySelector("#save-state");let tags=asset.tags.map(t=>({name:t.name,facet:t.facet})),richEditor=null;
  const message=(value,error=false)=>{saveState.textContent=value;saveState.className=error?"save-error":""};
  const paintTags=()=>{tagEditor.innerHTML=tags.map((t,i)=>`<button type="button" data-remove="${i}">${FACETS[t.facet]} · ${escapeHTML(t.name)} ×</button>`).join("");tagEditor.querySelectorAll("[data-remove]").forEach(b=>b.addEventListener("click",()=>{tags.splice(Number(b.dataset.remove),1);paintTags()}))};paintTags();
  const initRichEditor=()=>{if(richEditor)return richEditor;if(!window.Jodit)throw new Error("富文本编辑器加载失败，请刷新页面");richEditor=window.Jodit.make(richTextarea,{language:"zh_cn",height:390,minHeight:280,toolbarAdaptive:false,toolbarSticky:false,showCharsCounter:true,showWordsCounter:true,showXPathInStatusbar:false,askBeforePasteHTML:false,defaultActionOnPaste:"insert_as_html",buttons:["undo","redo","|","paragraph","|","bold","italic","underline","strikethrough","|","ul","ol","outdent","indent","|","link","image","table","hr","|","align","eraser","|","fullsize"],buttonsMD:["undo","redo","|","paragraph","|","bold","italic","underline","|","ul","ol","|","link","image","table","|","fullsize"],uploader:{url:`/api/assets/${asset.id}/embeds`,method:"POST",format:"json",filesVariableName:()=>"file",insertImageAsBase64URI:false,imagesExtensions:["jpg","jpeg","png","gif","webp"],isSuccess:response=>Boolean(response?.url),getMessage:response=>response?.error?.message||"图片上传失败",process:response=>({files:[response.url],path:"",baseurl:"",isImages:[true]})},placeholder:"记录正文，可直接粘贴截图或拖入图片…"});const managed=new RegExp(`^/api/assets/${asset.id}/embeds/[0-9a-f-]{36}$`),uploadFile=async file=>{if(file.size>20*1024*1024)throw new Error("单张图片不可超过 20 MiB");const body=new FormData();body.append("file",file,file.name||`pasted-${Date.now()}.png`);return api(`/api/assets/${asset.id}/embeds`,{method:"POST",body})},insertFiles=async files=>{message("正在保存粘贴的图片…");richEditor.s.save();try{for(const file of files){const result=await uploadFile(file);richEditor.s.restore();richEditor.s.insertImage(result.url);richEditor.s.save()}message("图片已保存到 Silo")}catch(error){message(error.message,true)}finally{richEditor.s.restore()}},captureFiles=event=>{const files=event.type==="paste"?[...(event.clipboardData?.items||[])].filter(item=>item.kind==="file"&&item.type.startsWith("image/")).map(item=>item.getAsFile()).filter(Boolean):[...(event.dataTransfer?.files||[])].filter(file=>file.type.startsWith("image/"));if(!files.length)return;event.preventDefault();event.stopPropagation();insertFiles(files)};richEditor.editor.addEventListener("paste",captureFiles,true);richEditor.editor.addEventListener("drop",captureFiles,true);new MutationObserver(()=>{if([...richEditor.editor.querySelectorAll("img")].some(image=>managed.test(image.getAttribute("src")||"")))message("图片已保存到 Silo")}).observe(richEditor.editor,{childList:true,subtree:true,attributes:true,attributeFilter:["src"]});richEditor.e.on("errorMessage",error=>message(String(error||"图片上传失败"),true));return richEditor};
  const waitForEditorImages=async()=>{const managed=new RegExp(`^/api/assets/${asset.id}/embeds/[0-9a-f-]{36}$`),deadline=Date.now()+15000;while(true){const doc=new DOMParser().parseFromString(initRichEditor().value,"text/html");let pending=false;for(const image of doc.body.querySelectorAll("img")){const src=image.getAttribute("src")||"";if(managed.test(src)){image.removeAttribute("srcset");continue}if(src.startsWith("data:image/")||src.startsWith("blob:")){pending=true;continue}throw new Error(src.startsWith("http")?"检测到外部图片。请复制图片本身或从电脑选择图片":"图片地址无效，请移除后重新粘贴")}if(!pending)return doc.body.innerHTML;if(Date.now()>=deadline)throw new Error("图片保存超时，请检查图片大小或重新粘贴");message("正在等待图片保存…");await new Promise(resolve=>setTimeout(resolve,100))}};
  const importMarkdownImages=async()=>{const editor=initRichEditor(),doc=new DOMParser().parseFromString(editor.value,"text/html"),walker=doc.createTreeWalker(doc.body,NodeFilter.SHOW_TEXT),nodes=[];while(walker.nextNode())nodes.push(walker.currentNode);let imported=0;for(const node of nodes){if(node.parentElement?.closest("pre,code"))continue;const text=node.nodeValue||"",pattern=/!\[([^\]]*)\]\\?\((\/(?:[^)\n]|%\d\d)+|~\/(?:[^)\n]|%\d\d)+)\)/g,matches=[...text.matchAll(pattern)];if(!matches.length)continue;const fragment=doc.createDocumentFragment();let cursor=0;for(const match of matches){fragment.append(text.slice(cursor,match.index));message("正在导入本地图片…");const result=await api(`/api/assets/${asset.id}/embeds/from-path`,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({path:match[2]})});const image=doc.createElement("img");image.src=result.url;if(match[1])image.alt=match[1];fragment.append(image);cursor=match.index+match[0].length;imported++}fragment.append(text.slice(cursor));node.replaceWith(fragment)}if(imported){editor.value=doc.body.innerHTML;message(`已导入 ${imported} 张本地图片`)}return imported};
  root.querySelector("#edit-button").addEventListener("click",()=>{form.hidden=!form.hidden;if(!form.hidden)initRichEditor().focus()});root.querySelector("#cancel-edit").addEventListener("click",()=>{form.hidden=true});root.querySelector("#add-detail-tag").addEventListener("click",()=>{const input=root.querySelector("#tag-name"),name=input.value.trim(),facet=root.querySelector("#tag-facet").value;if(name&&!tags.some(t=>t.name===name&&t.facet===facet)){tags.push({name,facet});input.value="";paintTags()}});
  const patch=async data=>{const updated=await api("/api/assets/"+asset.id,{method:"PATCH",headers:{"Content-Type":"application/json"},body:JSON.stringify({revision:asset.revision,...data})});return updated};
  form.addEventListener("submit",async event=>{event.preventDefault();saveButton.disabled=true;message("正在保存…");try{const data=new FormData(form);let metadata=null,analysis=null;try{const raw=String(data.get("metadata_json")||"").trim();metadata=raw?JSON.parse(raw):null}catch{throw new Error("元数据 JSON 格式有误，请检查括号、引号和逗号")}try{const raw=String(data.get("analysis_json")||"").trim();analysis=raw?JSON.parse(raw):null}catch{throw new Error("分析 JSON 格式有误，请检查括号、引号和逗号")}await importMarkdownImages();const contentHTML=await waitForEditorImages(),payload={title:data.get("title"),summary:data.get("summary"),core_value:data.get("core_value"),content_html:contentHTML,user_note:data.get("note"),asset_type:data.get("asset_type"),explore_level:data.get("explore_level"),status:data.get("status"),source_url:String(data.get("source_url")||"").trim()||null,canonical_url:String(data.get("canonical_url")||"").trim()||null,metadata_json:metadata,analysis_json:analysis,tags};message("正在保存资产…");await patch(payload);message("已保存");await detailPage(asset.id)}catch(error){saveButton.disabled=false;message(error.message,true);root.querySelector("#detail-message").innerHTML=`<div class="error">${escapeHTML(error.message)}</div>`}});
  root.querySelector("#archive-button").addEventListener("click",async()=>{try{await patch({status:asset.status==="active"?"archived":"active"});await detailPage(asset.id)}catch(error){root.querySelector("#detail-message").innerHTML=`<div class="error">${escapeHTML(error.message)}</div>`}});
  root.querySelector("#copy-button").addEventListener("click",async event=>{const button=event.currentTarget;if(button.disabled)return;try{await copyText(exploreInstruction(asset));button.disabled=true;button.classList.add("copy-success");button.innerHTML=ICON.check+"<span>已复制</span>";const feedback=root.querySelector("#copy-feedback");feedback.hidden=false;setTimeout(()=>feedback.hidden=true,2500)}catch{root.querySelector("#detail-message").innerHTML='<div class="error">复制失败，请使用页面中的资产 ID</div>'}});
}

async function newPage(){
  const choices=[['idea','灵感','先捕捉想法，之后分析价值与可行性'],['note','笔记','保存原始记录，再提炼要点与行动项'],['website','网站','记录一个网页或在线工具'],['github','GitHub','保存仓库地址，后续深入研究'],['article','文章','保存文章地址与阅读笔记'],['image','图片','保留原图和说明，之后进行视觉探索'],['pdf','PDF','保存文件并提取可读正文'],['html','HTML','保存单文件并提供安全静态预览'],['other','其他文件','保留暂未归类的本地资料']];
  const content=`<div class="content create-page"><button class="text-button back" data-back>${ICON.back}返回资产库</button><div class="create-heading"><div class="eyebrow">CAPTURE NOW, UNDERSTAND LATER</div><h1>记录一项新资产</h1><p>先保存原始内容，需要时再交给 Agent 深入探索。</p></div><form class="create-layout" id="create-form"><section class="panel create-main"><h2>选择内容类型</h2><div class="type-grid">${choices.map((c,i)=>`<button type="button" data-kind="${c[0]}" class="${i===0?'selected':''}">${typeIcon(c[0])}<span><strong>${c[1]}</strong><small>${c[2]}</small></span></button>`).join("")}</div><input type="hidden" name="kind" value="idea"><label>标题<input name="title" required maxlength="300" placeholder="给这项资料一个容易找回的名字"></label><label id="url-field" hidden>原始地址<input name="url" type="url" placeholder="https://…"></label><label class="asset-file" id="file-field" hidden><span>选择文件</span><span class="file-drop">${ICON.paperclip}<span id="file-label">点击选择，最大 20 MiB</span><input name="file" type="file"></span></label><label><span id="content-label">灵感内容</span><textarea name="content" rows="9" required placeholder="完整写下原始内容，AI 后续建议不会覆盖这里。"></textarea></label><label>为什么值得保留 <small>可选</small><input name="core_value" placeholder="它可能在哪个场景帮到你？"></label><label>主题标签 <small>可选，用逗号分隔</small><input name="tags" placeholder="例如：前端设计，自动化，知识管理"></label><div id="create-error"></div><div class="actions"><button class="primary">保存资产</button><button type="button" data-back>取消</button></div></section><aside class="panel explore-later">${ICON.lightbulb}<h2>保存后如何探索？</h2><p>进入资产详情复制探索指令，并交给当前 Agent。</p><ul><li>图片：识别真正目标并排除平台噪声</li><li>灵感：分析问题、用户、风险和下一步</li><li>笔记：整理要点、决定和行动项</li><li>网址：核实来源并形成完整报告</li></ul><p class="muted">原始内容始终保留，AI 报告独立展示。</p></aside></form></div>`;shell(content,"new","新建资产");
  root.querySelectorAll("[data-back]").forEach(b=>b.addEventListener("click",()=>navigate("/")));const form=root.querySelector("#create-form"),kindInput=form.elements.kind,fileKinds=["image","pdf","html","other"],urlKinds=["website","github","article"];
  root.querySelectorAll("[data-kind]").forEach(button=>button.addEventListener("click",()=>{root.querySelectorAll("[data-kind]").forEach(b=>b.classList.remove("selected"));button.classList.add("selected");const kind=button.dataset.kind;kindInput.value=kind;root.querySelector("#url-field").hidden=!urlKinds.includes(kind);root.querySelector("#file-field").hidden=!fileKinds.includes(kind);form.elements.url.required=urlKinds.includes(kind);form.elements.content.required=["idea","note"].includes(kind);form.elements.file.accept=kind==="image"?".png,.jpg,.jpeg,.gif,.webp":kind==="pdf"?".pdf":kind==="html"?".html,.htm":"";root.querySelector("#content-label").textContent=kind==="idea"?"灵感内容":kind==="note"?"笔记正文":kind==="image"?"图片说明":urlKinds.includes(kind)?"补充说明":"文件说明"}));
  form.elements.file.addEventListener("change",()=>{root.querySelector("#file-label").textContent=form.elements.file.files[0]?.name||"点击选择，最大 20 MiB"});
  form.addEventListener("submit",async e=>{e.preventDefault();const data=new FormData(form),kind=data.get("kind"),file=data.get("file"),tags=String(data.get("tags")||"").split(/[,，]/).map(x=>x.trim()).filter(Boolean).map(name=>({name,facet:"domain"}));try{let result;if(fileKinds.includes(kind)){if(!file||!file.size)throw new Error("请选择要保存的文件");const body=new FormData();body.append("file",file);body.append("title",data.get("title"));body.append("asset_type",kind);body.append("description",data.get("content"));body.append("core_value",data.get("core_value"));body.append("tags_json",JSON.stringify(tags));result=await api("/api/assets/upload",{method:"POST",body})}else{const payload={title:data.get("title"),asset_type:kind,content_text:data.get("content"),summary:String(data.get("content")||"").trim().replace(/\s+/g," ").slice(0,180),core_value:data.get("core_value"),tags,explore_level:"basic"};if(urlKinds.includes(kind))payload.source_url=data.get("url");result=await api("/api/assets",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(payload)})}navigate("/assets/"+result.asset.id)}catch(error){root.querySelector("#create-error").innerHTML=`<div class="error">${escapeHTML(error.message)}</div>`}});
}

async function importPage(){const content=`<div class="content import-page"><div class="eyebrow">BRING YOUR COLLECTION HOME</div><h1>导入收藏夹</h1><p class="lead">把浏览器里的发现，带进你的信息筒仓。</p><section class="panel upload-panel"><div class="empty-icon">${ICON.upload}</div><h2>选择浏览器导出的 HTML 文件</h2><p>保留名称、链接和收藏目录，并自动添加基础分类标签。</p><label class="file-picker">选择收藏夹文件<input id="bookmark-file" type="file" accept=".html,.htm"></label><div class="actions"><button class="primary" id="preview-import" disabled>预检收藏夹</button><button id="commit-import" hidden>确认导入</button></div><small>最多 10,000 条链接 · 20 MiB · 不自动访问网页</small></section><div id="import-result"></div><section class="import-help"><h2>如何导出收藏夹？</h2><p>在 Chrome 或 Edge 的收藏夹管理器中选择“导出书签／收藏夹”，保存为 HTML 文件。</p></section></div>`;shell(content,"import","导入收藏夹");const file=root.querySelector("#bookmark-file"),preview=root.querySelector("#preview-import"),commit=root.querySelector("#commit-import"),result=root.querySelector("#import-result");file.addEventListener("change",()=>{preview.disabled=!file.files.length;commit.hidden=true;result.innerHTML=""});const run=async isPreview=>{const body=new FormData();body.append("file",file.files[0]);try{const data=await api("/api/imports/bookmarks"+(isPreview?"/preview":""),{method:"POST",body});commit.hidden=!data.preview;result.innerHTML=`<section class="panel"><h2>${data.preview?"预检结果":"导入完成"}</h2><div class="import-stats"><div><b>${data.total}</b>链接总数</div><div><b>${data.added}</b>${data.preview?"预计新增":"已新增"}</div><div><b>${data.duplicate}</b>重复链接</div><div><b>${data.failed}</b>无效链接</div></div>${data.errors.map(e=>`<p>第 ${e.row} 条 · ${escapeHTML(e.url)}<br>${escapeHTML(e.error)}</p>`).join("")}</section>`}catch(error){result.innerHTML=`<div class="error">${escapeHTML(error.message)}</div>`}};preview.addEventListener("click",()=>run(true));commit.addEventListener("click",()=>run(false))}

function discoveryMetrics(item){const m=item.metrics_json||{};if(item.item_type==='github')return [m.stars!=null?`★ ${Number(m.stars).toLocaleString()}`:'',m.forks!=null?`⑂ ${Number(m.forks).toLocaleString()}`:'',m.language||'',m.license||''].filter(Boolean);return [m.points!=null?`${m.points} 分`:'',m.comments!=null?`${m.comments} 条讨论`:'',item.author||''].filter(Boolean)}

async function discoveryPage(interested=false){
  showLoading(interested?'感兴趣':'发现');const params=new URLSearchParams(location.search);const state=interested?'interested':(params.get('state')||'new');const itemType=params.get('item_type')||'';
  try{const query=new URLSearchParams(params);query.set('state',state);if(itemType)query.set('item_type',itemType);else query.delete('item_type');const [results,sources,rules,facets]=await Promise.all([api('/api/discovery/items?'+query),api('/api/discovery/sources'),api('/api/discovery/rules'),api('/api/discovery/facets?state='+encodeURIComponent(state))]);
    const cards=results.items.map(item=>{const metrics=discoveryMetrics(item).map(x=>`<span>${escapeHTML(x)}</span>`).join('');const topics=(item.topics_json||[]).slice(0,5).map(x=>`<span class="tag">${escapeHTML(x)}</span>`).join('');return `<article class="discovery-card" data-id="${item.id}"><div class="discovery-main">${typeIcon(item.item_type)}<div><div class="discovery-title"><a href="${escapeHTML(item.url)}" target="_blank" rel="noreferrer">${escapeHTML(item.title)}</a><span>${escapeHTML(item.source_name)}</span></div><p>${escapeHTML(item.summary||'来源暂未提供摘要。')}</p><div class="discovery-meta">${metrics}${topics}</div></div></div><div class="discovery-actions">${item.state==='saved'&&item.asset_id?`<button data-open="${item.asset_id}">查看资产</button><button data-explore="${item.asset_id}">${ICON.copy}探索指令</button>`:`<button class="primary" data-save>保存</button><button data-interest>${item.state==='interested'?'移出感兴趣':'感兴趣'}</button><button class="text-button" data-dismiss>忽略</button>`}</div></article>`}).join('');
    const tabs=`<div class="discover-tabs"><button data-type="" class="${!itemType?'active':''}">全部</button><button data-type="github" class="${itemType==='github'?'active':''}">GitHub</button><button data-type="article" class="${itemType==='article'?'active':''}">技术文章</button><button data-state="saved" class="${state==='saved'?'active':''}">已保存</button></div>`;
    const sourceRows=sources.map(s=>`<div class="source-chip ${s.last_error?'has-error':''} ${params.get('source_id')===s.id?'active':''}"><button class="source-select" data-source="${s.id}" title="只看 ${escapeHTML(s.name)}"><strong>${escapeHTML(s.name)}</strong><span>${s.last_checked_at?`更新于 ${dateTime(s.last_checked_at)}`:'尚未刷新'}${s.last_error?` · 刷新失败`:''}</span></button><button title="实时刷新 ${escapeHTML(s.name)}" aria-label="实时刷新 ${escapeHTML(s.name)}" data-refresh="${s.id}">${ICON.refresh}</button></div>`).join('');
    const facetFilters=`<div class="discover-facets"><label>来源<select data-discovery-filter="source_id"><option value="">全部来源</option>${sources.map(x=>`<option value="${x.id}" ${params.get('source_id')===x.id?'selected':''}>${escapeHTML(x.name)}</option>`).join('')}</select></label><label>语言<select data-discovery-filter="language"><option value="">全部语言</option>${facets.languages.map(x=>`<option value="${escapeHTML(x.name)}" ${params.get('language')===x.name?'selected':''}>${escapeHTML(x.name)} · ${x.count}</option>`).join('')}</select></label><label>主题<select data-discovery-filter="topic"><option value="">全部主题</option>${facets.topics.map(x=>`<option value="${escapeHTML(x.name)}" ${params.get('topic')===x.name?'selected':''}>${escapeHTML(x.name)} · ${x.count}</option>`).join('')}</select></label>${params.get('source_id')?'<button class="text-button" data-clear-source>清除来源筛选</button>':''}</div>`;
    const content=`<div class="content discover-page"><div class="page-title discover-hero"><div><div class="eyebrow">DISCOVER WITHOUT AI</div><h1>${interested?'感兴趣':'发现新内容'}</h1><p>${interested?'稍后判断是否值得进入正式资产库。':'从 GitHub、Hacker News 和订阅源中筛选值得留下的内容。'}</p></div><button class="primary" id="refresh-all">${ICON.refresh}<span>刷新全部</span></button></div><div id="discover-message"></div><section class="discover-tools"><div class="source-manager"><div class="tool-heading"><div><h2>内容来源</h2><p>${sources.length} 个公开来源，可单独刷新或添加订阅。</p></div><details><summary>${ICON.plus}添加 RSS / Atom</summary><form id="source-form"><input name="name" required placeholder="来源名称"><input name="url" type="url" required placeholder="https://example.com/feed.xml"><button>添加订阅</button></form></details></div><div class="source-grid">${sourceRows}</div></div><div class="rule-manager"><div class="tool-heading"><div><h2>兴趣规则</h2><p>刷新时按关键词、语言和 Star 门槛调整排序。</p></div><details><summary>${ICON.plus}新建规则</summary><form id="rule-form"><input name="name" required placeholder="规则名称"><input name="include" placeholder="关注词，逗号分隔"><input name="exclude" placeholder="排除词，逗号分隔"><input name="languages" placeholder="语言，逗号分隔"><input name="min_stars" type="number" min="0" value="0" placeholder="最低 Star"><button>保存规则</button></form></details></div><div class="rule-list">${rules.map(r=>`<div class="rule-chip"><strong>${escapeHTML(r.name)}</strong><span>${escapeHTML(r.include_keywords_json.join('、')||r.languages_json.join('、')||'自定义规则')}</span></div>`).join('')||'<span class="muted">还没有规则，内容先按来源热度排序。</span>'}</div></div></section>${tabs}<form class="discover-search" id="discover-search">${ICON.search}<input name="q" value="${escapeHTML(params.get('q')||'')}" placeholder="筛选标题、摘要、作者或主题"><button>筛选</button></form>${facetFilters}<section class="discover-results"><div class="list-heading"><span>${results.total} 条内容</span><div>按兴趣分和热度排序</div></div><div class="discovery-list">${cards||`<div class="empty"><div class="empty-icon">${ICON.compass}</div><h2>${interested?'还没有标记感兴趣的内容':'还没有发现内容'}</h2><p>${interested?'在发现页看到想稍后判断的内容时，点“感兴趣”。':'刷新内置来源，或者添加自己的 RSS/Atom 订阅。'}</p></div>`}</div></section></div>`;
    shell(content,interested?'interested':'discover',interested?'感兴趣':'发现');bindDiscovery(interested,state,sources);
  }catch(error){showError(error,interested?'感兴趣':'发现')}
}

function bindDiscovery(interested,state,sources){
  const message=root.querySelector('#discover-message');const post=async(url,body={})=>api(url,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});
  root.querySelectorAll('[data-type]').forEach(b=>b.addEventListener('click',()=>{const p=new URLSearchParams(location.search);p.delete('state');if(b.dataset.type)p.set('item_type',b.dataset.type);else p.delete('item_type');navigate((interested?'/interested':'/discover')+'?'+p)}));
  root.querySelector('[data-state]')?.addEventListener('click',()=>navigate('/discover?state=saved'));
  root.querySelectorAll('[data-discovery-filter]').forEach(select=>select.addEventListener('change',()=>{const p=new URLSearchParams(location.search);select.value?p.set(select.dataset.discoveryFilter,select.value):p.delete(select.dataset.discoveryFilter);navigate((interested?'/interested':'/discover')+'?'+p)}));
  root.querySelectorAll('[data-source]').forEach(button=>button.addEventListener('click',()=>{const p=new URLSearchParams(location.search);p.set('source_id',button.dataset.source);navigate((interested?'/interested':'/discover')+'?'+p)}));
  root.querySelector('[data-clear-source]')?.addEventListener('click',()=>{const p=new URLSearchParams(location.search);p.delete('source_id');navigate((interested?'/interested':'/discover')+'?'+p)});
  root.querySelector('#discover-search')?.addEventListener('submit',e=>{e.preventDefault();const p=new URLSearchParams(location.search),q=new FormData(e.target).get('q');q?p.set('q',q):p.delete('q');navigate((interested?'/interested':'/discover')+'?'+p)});
  root.querySelectorAll('[data-interest]').forEach(b=>b.addEventListener('click',async()=>{await post(`/api/discovery/items/${b.closest('[data-id]').dataset.id}/state`,{state:interested?'new':'interested'});discoveryPage(interested)}));
  root.querySelectorAll('[data-dismiss]').forEach(b=>b.addEventListener('click',async()=>{await post(`/api/discovery/items/${b.closest('[data-id]').dataset.id}/state`,{state:'dismissed'});discoveryPage(interested)}));
  root.querySelectorAll('[data-save]').forEach(b=>b.addEventListener('click',async()=>{b.disabled=true;try{const r=await post(`/api/discovery/items/${b.closest('[data-id]').dataset.id}/save`);message.innerHTML=`<div class="notice">${ICON.check}已保存为基础资产：${escapeHTML(r.asset.title)}。需要时可在资产详情复制探索指令。</div>`;discoveryPage(interested)}catch(e){message.innerHTML=`<div class="error">${escapeHTML(e.message)}</div>`;b.disabled=false}}));
  root.querySelectorAll('[data-open]').forEach(b=>b.addEventListener('click',()=>navigate('/assets/'+b.dataset.open)));
  root.querySelectorAll('[data-explore]').forEach(b=>b.addEventListener('click',async()=>{const asset=await api('/api/assets/'+b.dataset.explore);await copyText(exploreInstruction(asset));b.innerHTML=ICON.check+'已复制';b.disabled=true}));
  const refresh=async(sourceId,staleOnly=false)=>{message.innerHTML=`<div class="notice">${staleOnly?'缓存已超过 30 分钟，正在后台联网获取最新内容…':'正在实时联网读取公开来源…'}</div>`;try{const r=await post('/api/discovery/refresh',sourceId?{source_id:sourceId}:{stale_only:staleOnly});const rows=r.results||[r];if(staleOnly&&!rows.length){message.innerHTML='';return}const ok=rows.filter(x=>!x.error).reduce((n,x)=>n+(x.added||0),0),errors=rows.filter(x=>x.error);message.innerHTML=`<div class="notice">${ICON.check}${staleOnly?'自动更新':'实时刷新'}完成，新增 ${ok} 条${errors.length?`，${errors.length} 个来源失败`:''}。</div>`;setTimeout(()=>discoveryPage(interested),500)}catch(e){message.innerHTML=`<div class="error">${escapeHTML(e.message)}</div>`}};
  root.querySelector('#refresh-all')?.addEventListener('click',()=>refresh());root.querySelectorAll('[data-refresh]').forEach(b=>b.addEventListener('click',()=>refresh(b.dataset.refresh)));
  root.querySelector('#source-form')?.addEventListener('submit',async e=>{e.preventDefault();const d=new FormData(e.target);try{await post('/api/discovery/sources',{source_type:'rss',name:d.get('name'),url:d.get('url')});discoveryPage(interested)}catch(error){message.innerHTML=`<div class="error">${escapeHTML(error.message)}</div>`}});
  root.querySelector('#rule-form')?.addEventListener('submit',async e=>{e.preventDefault();const d=new FormData(e.target),split=v=>String(v||'').split(/[,，]/).map(x=>x.trim()).filter(Boolean);try{await post('/api/discovery/rules',{name:d.get('name'),include_keywords:split(d.get('include')),exclude_keywords:split(d.get('exclude')),languages:split(d.get('languages')),topics:[],min_stars:Number(d.get('min_stars')||0)});discoveryPage(interested)}catch(error){message.innerHTML=`<div class="error">${escapeHTML(error.message)}</div>`}});
  const cutoff=Date.now()-30*60*1000;if(sources.some(s=>!s.last_checked_at||new Date(s.last_checked_at).getTime()<cutoff))refresh(null,true);
}

async function dataPage(){
  showLoading("数据管理");
  try{
    const [stats,sync]=await Promise.all([api('/api/data/stats'),api('/api/data/sync/status')]);
    const modeLabel={standalone:'单机模式',server:'同步服务端',client:'同步客户端'}[sync.mode]||sync.mode;
    const content=`<div class="content data-page"><div class="eyebrow">PORTABLE BY DESIGN</div><h1>数据管理</h1><p class="lead">备份个人数据，恢复以前的导出，或生成不包含个人信息的空白 Skill。</p><div id="data-message"></div>
      <section class="panel sync-card"><div><div class="section-title"><h2>设备同步</h2><span class="sync-badge ${sync.enabled?'online':'offline'}">${escapeHTML(modeLabel)}</span></div><p>${sync.mode==='client'?'服务运行期间自动上传本机修改并拉取服务端数据。':sync.mode==='server'?'作为内网同步中心保存完整资产与附件。':'当前数据只保存在这台设备。'}</p></div><dl><div><dt>设备 ID</dt><dd>${escapeHTML(sync.device_id||'未配置')}</dd></div>${sync.server_url?`<div><dt>服务端</dt><dd>${escapeHTML(sync.server_url)}</dd></div>`:''}<div><dt>待上传</dt><dd>${sync.pending}</dd></div><div><dt>同步游标</dt><dd>${sync.cursor}</dd></div><div><dt>最近成功</dt><dd>${sync.last_success_at?dateTime(sync.last_success_at):'尚未同步'}</dd></div></dl>${sync.last_error?`<div class="sync-error">${escapeHTML(sync.last_error)}</div>`:''}${sync.mode==='client'&&sync.enabled?'<button class="primary" id="sync-now">立即同步</button>':''}</section>
      <section class="data-grid">
        <article class="panel data-card"><div class="data-icon">${ICON.download}</div><h2>导出个人数据备份</h2><p>包含 SQLite 数据库、配置和所有附件，可在另一份 Silo 中完整恢复。</p><dl><div><dt>全部资产</dt><dd>${stats.assets}</dd></div><div><dt>附件</dt><dd>${stats.attachments}</dd></div><div><dt>附件大小</dt><dd>${(stats.storage_bytes/1024/1024).toFixed(2)} MiB</dd></div></dl><a class="button primary" href="/api/data/export">${ICON.download}下载数据备份</a></article>
        <article class="panel data-card"><div class="data-icon">${ICON.database}</div><h2>分享空白 Silo</h2><p>下载完整可运行的 Skill，但数据库是新建的空库，不包含你的资产、标签、报告或附件。</p><a class="button" href="/api/data/share-package">${ICON.download}下载空白 Skill</a></article>
      </section>
      <section class="panel restore-card"><h2>从数据备份恢复</h2><p>恢复会用备份中的数据库、配置和附件替换当前内容。系统会先校验格式、数据库完整性和附件。</p><label class="asset-file"><span>选择 Silo 数据备份 ZIP</span><span class="file-drop">${ICON.paperclip}<span id="restore-label">点击选择备份文件</span><input id="restore-file" type="file" accept=".zip,application/zip"></span></label><label>输入“恢复备份”确认<input id="restore-confirm" autocomplete="off" placeholder="恢复备份"></label><button id="restore-button" disabled>恢复备份</button></section>
      <section class="panel danger-zone"><h2>清空全部数据</h2><p>永久移除当前数据库中的资产、标签、探索报告和全部附件，并建立一个全新空库。此操作不会自动留下备份。</p><label>输入“清空全部数据”确认<input id="clear-confirm" autocomplete="off" placeholder="清空全部数据"></label><button class="danger-button" id="clear-button" disabled>清空全部数据</button></section>
    </div>`;
    shell(content,'data','数据管理');bindDataPage();
  }catch(error){showError(error,'数据管理')}
}

function bindDataPage(){
  const message=root.querySelector('#data-message'),restoreFile=root.querySelector('#restore-file'),restoreConfirm=root.querySelector('#restore-confirm'),restoreButton=root.querySelector('#restore-button'),clearConfirm=root.querySelector('#clear-confirm'),clearButton=root.querySelector('#clear-button');
  const updateRestore=()=>restoreButton.disabled=!(restoreFile.files.length&&restoreConfirm.value==='恢复备份');restoreFile.addEventListener('change',()=>{root.querySelector('#restore-label').textContent=restoreFile.files[0]?.name||'点击选择备份文件';updateRestore()});restoreConfirm.addEventListener('input',updateRestore);clearConfirm.addEventListener('input',()=>clearButton.disabled=clearConfirm.value!=='清空全部数据');
  restoreButton.addEventListener('click',async()=>{restoreButton.disabled=true;message.innerHTML='<div class="notice">正在校验并恢复备份…</div>';const body=new FormData();body.append('file',restoreFile.files[0]);body.append('confirmation',restoreConfirm.value);try{const result=await api('/api/data/restore',{method:'POST',body});message.innerHTML=`<div class="notice">${ICON.check}恢复完成，共 ${result.stats.assets} 项资产。</div>`;setTimeout(()=>navigate('/'),700)}catch(error){message.innerHTML=`<div class="error">${escapeHTML(error.message)}</div>`;updateRestore()}});
  clearButton.addEventListener('click',async()=>{clearButton.disabled=true;message.innerHTML='<div class="notice">正在建立空数据库…</div>';try{await api('/api/data/clear',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({confirmation:clearConfirm.value})});message.innerHTML=`<div class="notice">${ICON.check}数据已经清空。</div>`;setTimeout(()=>navigate('/'),700)}catch(error){message.innerHTML=`<div class="error">${escapeHTML(error.message)}</div>`;clearButton.disabled=false}});
  root.querySelector('#sync-now')?.addEventListener('click',async event=>{const button=event.currentTarget;button.disabled=true;message.innerHTML='<div class="notice">正在与服务端同步…</div>';try{const result=await api('/api/data/sync/run',{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'});message.innerHTML=`<div class="notice">${ICON.check}同步完成：上传 ${result.pushed} 条，应用 ${result.applied} 条。</div>`;setTimeout(dataPage,700)}catch(error){message.innerHTML=`<div class="error">${escapeHTML(error.message)}</div>`;button.disabled=false}});
}

async function render(){const path=location.pathname;if(path==="/new")return newPage();if(path==="/import")return importPage();if(path==="/discover")return discoveryPage(false);if(path==="/interested")return discoveryPage(true);if(path==="/data")return dataPage();const match=path.match(/^\/assets\/([^/]+)$/);if(match)return detailPage(match[1]);return libraryPage()}
window.addEventListener("popstate",render);
window.addEventListener("focus",()=>{const match=location.pathname.match(/^\/assets\/([^/]+)$/);if(match&&root.querySelector("#edit-form")?.hidden)detailPage(match[1])});
render();
